/// Rows of the cell above the baseline.
pub const ASCENT: i32 = 11;

/// Rows of the cell below the baseline. Non-zero: this face has real
/// descenders, so the cell is taller than the cap height.
pub const DESCENT: i32 = 3;

/// Pen movement from one glyph to the next, in font pixels. The face is
/// monospaced, so this is a constant rather than a per-glyph table.
pub const ADVANCE: i32 = 7;

/// Baseline to the top of a capital, in font pixels.
